156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
159	        if (ownerFieldsDto != null) {
160	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
161	        }
162	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
163	        if (!missingFields.isEmpty()) {
164	            throw new MissingOwnerFieldsException(missingFields);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        Collection<Owner> sameLastName =
169	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
170	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
171	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
172	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
173	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        owner.setTelephone(normalizedTelephone);
177	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
178	        if (owner.getRegistrationDate() == null) {
179	            owner.setRegistrationDate(LocalDate.now());
180	        }
181	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
182	        LocalDate registrationDate = owner.getRegistrationDate();
183	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
184	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
185	            throw new DailyOwnerLimitException(registrationDate);
186	        }
187	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
188	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
189	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
190	            throw new CityOwnerLimitException(owner.getCity());
191	        }
192	        owner.setCustomerCode(customerCodeGenerator.generate(
193	            owner.getCity(), owner.getLastName(), cityOwnerCount));
194	        this.clinicService.saveOwner(owner);
195	        ownerAuditLogger.ownerCreated(owner);
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
