23	/**
24	 * Emits audit-trail entries for owner lifecycle events to the dedicated {@code AUDIT}
25	 * logger, keeping audit concerns out of the request-handling controller.
26	 */
27	@Component
28	public class OwnerAuditLogger {
29	
30	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
31	
32	    /**
33	     * Record that an owner was successfully created, capturing its id, customer code
34	     * and registration date.
35	     *
36	     * @param owner the persisted owner
37	     */
38	    public void ownerCreated(Owner owner) {
39	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
40	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
41	    }
42	}
